"""Generate 30 standalone text-rich slide prompts, three batches and a ZIP."""
from pathlib import Path
import json, zipfile
R=Path(__file__).resolve().parent
d=json.loads((R/"content/lesson.json").read_text(encoding="utf-8-sig"))
specs=json.loads((R/"content/slide-specs.json").read_text(encoding="utf-8-sig"))
out=R/"assets/prompts_v3"
out.mkdir(parents=True,exist_ok=True)
(out/"batches").mkdir(exist_ok=True)
style="""Создай ОДИН законченный информативный учебный слайд, а не фон, не обложку и не набор немых пиктограмм. Используй встроенную генерацию изображений ChatGPT, доступную в текущем чате. Формат строго 16:9, предпочтительно 1920×1080. Не называй 1792×1024 форматом 16:9. Не склеивай несколько слайдов в один.
ДНК BUSINESS INTELLIGENCE 2026: чистый белый #FFFFFF; заголовки deep navy #002060; акцент electric blue #0047FF; заливки #E5EFFF; тонкие нейтральные контуры #F2F2F2. Inter/Golos Text/Montserrat по характеру; крупные русские заголовки ExtraBold, подзаголовки Bold с вертикальным синим маркером; основной текст тёмный, интерлиньяж 130%. При 1920×1080: заголовок 48–60 px, названия карточек 28–34, пояснения не менее 24. Основной смысл должен читаться при показе на экране.
Сетка: верхние 13–15% — заголовок и короткая мысль; 62–65% — содержательная инфографика с 4–6 карточками (если дано другое число, следуй указанной структуре); следующие 10–12% — конкретный пример и главный вывод; нижние 10–12% — единый бренд-футер. Карточки со скруглением 12–15 px и внутренними отступами не менее 30 px. Не оставляй пустой центр, широкое пустое поле под HTML-текст или карточки без описаний. Воздух служит читаемости, не заменяет содержание.
Графика: согласованные outline-иконки, тонкие стрелки реальной смысловой связи, документные миниатюры и лёгкая объёмность карточек. Светлые дорожки печатной платы только в углах и нижней зоне. Никаких роботов, случайных диаграмм, псевдокода, вымышленных чисел, настоящих служебных документов или сходства с реальными сотрудниками.
Футер на всю ширину, deep navy, верхние углы слегка скруглены. Слева две белые строки: «БОЛЬШИЕ ЯЗЫКОВЫЕ МОДЕЛИ» и «ТЕХНОЛОГИИ, КОТОРЫЕ РАСШИРЯЮТ ВОЗМОЖНОСТИ ЧЕЛОВЕКА». В центре тонкий синий circuit-pattern. Справа повтори предоставленную полосу-референс с двумя существующими знаками: угловатый сине-красный геометрический знак НОЦ ВКО с подписью из оригинала; затем тонкий вертикальный разделитель; знак Клуба «ИИ в образовании» — академическая шапочка и стилизованный интеллект, над ним «КЛУБ», рядом «ИИ в образовании». В крайней правой части малый слоган из референса. Не подменяй подпись организации на «Алтайский край», не выдумывай герб и не исправляй название по памяти. Точно переноси оригинальный футер как предоставленный графический элемент. Если референс футера не приложен, запроси его перед генерацией; не создавай похожие логотипы с ложными надписями.
ВСЕ русские подписи, описания карточек, пример и вывод ниже должны быть частью изображения, как в референсе «Шесть ворот до отправки данных». Не добавляй служебные фразы «заголовок», «пример для генератора», имя файла или инструкции. Не копируй ошибки букв из референса. Не помещай длинный текст источника в микрошрифт. Если текст не помещается, перестрой сетку и укороти декоративную графику, но не убирай смысловые пояснения."""
intro="""# Инструкция для нового чата — отправить ПЕРЕД пакетом из 10 промптов

1. Прикрепите references/six-gates-reference.png как эталон плотности и читаемости и references/brand-footer-reference.png как исходную полосу футера с логотипами. Эти два исходных референса включены в ZIP. Не прикрепляйте пустые изображения как эталон результата.
2. Скопируйте текст ниже в новый чат ChatGPT с доступной встроенной генерацией изображений.
3. Загрузите ОДИН файл batches/... с 10 промптами. Это десять самостоятельных изображений, не одна мозаика.
4. Начните с первого номера. Проверьте русский текст, факты, футер и читаемость. Затем продолжайте по одному номеру или в доступном интерфейсу режиме. Не рассчитывайте, что одно сообщение гарантированно создаст все десять файлов.
5. Каждый файл сохраняйте с именем, указанным у промпта. 30 промптов подготовлены; новые PNG этим комплектом не генерировались.

## Текст для вставки

Ты создаёшь законченные учебные слайды курса ДПО. Действуй как информационный дизайнер. Приложенный слайд — эталон информативности, а полоса футера — точный бренд-элемент. Используй только встроенную генерацию изображений ChatGPT, доступную в этом чате; не обещай конкретное название модели, если интерфейс его не показывает.

Главное изменение относительно прежней версии: ТЕКСТ ОБЯЗАТЕЛЕН ВНУТРИ ИЗОБРАЖЕНИЯ. В каждом промпте даны точный заголовок, русские описания карточек, пример и вывод. Это содержательная учебная инфографика, не пустой фон для последующей вёрстки. Не выдавай схему из одних значков. Приоритет: смысл → читаемость → визуальная иерархия → декор.

Сгенерируй только текущий слайд. Не объединяй десять промптов в коллаж. Не вставляй название промпта и имя файла в изображение. Перед выдачей проверь русские буквы и всю арифметику. Не добавляй факты, статистику или правовые обещания. Перед следующим слайдом сохраняй ту же ДНК, но меняй композицию согласно конкретному промпту. Логотипы копируй из предоставленного футера, а не сочиняй. Если обязательного референса нет — сначала запроси его.

Первым создай слайд с наименьшим номером из загруженного пакета. Далее я напишу «следующий».
"""
(out/"00_CHAT_INSTRUCTION.md").write_text(intro,encoding="utf-8")
(out/"SLIDE_DNA_V3.md").write_text("# ДНК слайдов V3\n\n"+style+"\n\nВладелец проекта прямо запросил русские текстовые описания внутри изображения. Это изменение задания относительно прежних промптов «no text»; установленные skills не изменяются.\n",encoding="utf-8")
prompts=[]
index=["# 30 промптов — текстовая инфографика V3","Версия 21.09.2026. Все темы синхронизированы с уроком 90 + 90 минут. Старые V2 сохранены как предыдущая версия; для новой генерации используйте только V3.","[Начните с инструкции для чата](00_CHAT_INSTRUCTION.md). Затем прикрепите один пакет из десяти.","| № | Пара / блок | Тема | Имя PNG |\n|---:|---|---|---|"]
for sec in d["sections"]:
    for sl in sec["slides"]:
        n=sl["id"]
        _,scene,cards=specs[n-1]
        cards_text="\n".join(f'{i+1}. Заголовок «{c.split("|",1)[0]}». Описание «{c.split("|",1)[1]}».' for i,c in enumerate(cards))
        # Concise but concrete examples taken verbatim from reviewed lesson.
        example=sl["example"]
        source=""
        if n==26: source="Короткая строка источника: «Mata v. Avianca · судебный акт, 2023». Не изображай это российским делом."
        if n==28: source="Метка: «СИНТЕТИЧЕСКИЕ ПРОФИЛИ · УЧЕБНЫЙ ЭТАЛОН». 5 и 5 — расчёт по учебной рубрике, не ответы реальных моделей."
        if n==29: source="Метка: «УЧЕБНЫЙ СЦЕНАРИЙ». Не изображай «99% дипфейк»: визуальный детектор достоверность не гарантирует."
        prompt=f"""## ПРОМПТ {n:03d} — {sl["title"]}

Имя результата: slide_{n:03d}_v2.png
Место в уроке: пара {sec["pair"]}, {sec["title"]}, блок {sec["start"]}–{sec["end"]} мин.
Это технические сведения для исполнителя, НЕ печатать их целиком на слайде.

### Задача и точная композиция
{scene}
Учебный смысл для дизайнера: {sl["explanation"]}
Не переписывай весь этот абзац на слайд: визуализируй связь с помощью карточек и примера, заданных ниже.

### ТЕКСТ, КОТОРЫЙ НУЖНО НАПЕЧАТАТЬ НА ИЗОБРАЖЕНИИ
Главный заголовок: «{sl["title"].upper()}».
Карточки:
{cards_text}
Выделенный пример в отдельной компактной полосе: «{example}»
Главный вывод: «{sl["takeaway"]}»
{source}

### Общая ДНК — обязательна для этого отдельного изображения
{style}

### Самопроверка перед выдачей
Проверь: заголовок присутствует; каждая карточка содержит описание; есть конкретный пример и вывод; текст не обрезан и не превратился в псевдобуквы; стрелки объясняют смысл; цифры и ограничения сохранены; футер совпадает с предоставленным оригиналом; центральная область содержательная. Никаких новых обещаний «полностью безопасно», «100% анонимно», «можно загружать любые данные» или «ИИ гарантирует законность».
"""
        prompts.append(prompt)
        index.append(f'| {n:03d} | {sec["pair"]} / {sec["id"]} | {sl["title"]} | slide_{n:03d}_v2.png |')
for b in range(3):
    name=f'{b+1:02d}_prompts_{b*10+1:03d}-{(b+1)*10:03d}_v3.md'
    content=f"# Пакет {b+1}: промпты {b*10+1:03d}–{(b+1)*10:03d}\n\nСначала используйте ../00_CHAT_INSTRUCTION.md. По одному изображению на промпт.\n\n"+"\n\n---\n\n".join(prompts[b*10:(b+1)*10])
    (out/"batches"/name).write_text(content,encoding="utf-8")
index+=["","## Пакеты","- [001–010](batches/01_prompts_001-010_v3.md)","- [011–020](batches/02_prompts_011-020_v3.md)","- [021–030](batches/03_prompts_021-030_v3.md)","","## Куда положить готовые слайды",r"Рабочая папка приёма: C:\2026 программы\cloude code\аЛМАЗ аНТЕЙ\DPO-1_4\assets\slides",r"Имена: slide_001_v2.png … slide_030_v2.png. Суффикс v2 оставлен только ради совместимости существующих адресов HTML; содержание генерируется по V3.","Сайт не следит за диском автоматически. После проверки текста и замены файлов требуется отдельный commit/push и успешная сборка GitHub Pages. Массовую генерацию или загрузку картинок этот пакет не выполняет.","Промпты 001–010 относятся к первой группе слайдов; пакет не равен паре. Граница двух пар проходит между слайдами 021 и 022.","## Проверка готового PNG","Откройте в масштабе показа: все карточки читаемы, кириллица без ошибок, примеры совпадают с текстом урока, логотипы и подписи не подменены. Если повреждена надпись, исправьте конкретную область генератором; не принимайте изображение только за цветовую похожесть."]
(out/"README.md").write_text("\n\n".join(index)+"\n",encoding="utf-8")
zip_path=R/"downloads/slide-prompts-v3.zip"
with zipfile.ZipFile(zip_path,"w",zipfile.ZIP_DEFLATED) as z:
    for p in sorted(out.rglob("*")):
        if p.is_file(): z.write(p,p.relative_to(out))
with zipfile.ZipFile(zip_path) as z:
    assert len(z.namelist())==8
assert len(prompts)==30
print("30 prompts / 3 batches; ZIP verified, 6 Markdown files + 2 user-supplied references")
